SELECT obj_description('int4pl'::regproc, 'pg_proc'), obj_description('pg_catalog'::regnamespace, 'pg_namespace'), obj_description('int4'::regtype, 'pg_type'), col_description('pg_class'::regclass, 1);
COMMENT ON FUNCTION int4pl(int4, int4) IS 'mine';
SELECT obj_description('int4pl'::regproc, 'pg_proc'), (SELECT description FROM pg_description WHERE objoid = 'int4pl'::regproc);
COMMENT ON FUNCTION int4pl(int4, int4) IS NULL;
SELECT obj_description('int4pl'::regproc, 'pg_proc'), (SELECT count(*) FROM pg_description WHERE objoid = 'int4pl'::regproc);
SELECT amproc FROM pg_amproc WHERE amprocfamily = 434 AND amprocnum = 3 ORDER BY oid LIMIT 2;
SELECT oprcode, oprrest, oprjoin FROM pg_operator WHERE oid = 'int4pl'::regproc::oid OR oprname = '+' AND oprleft = 23 AND oprright = 23;
SELECT relname, relkind, reltoastrelid::regclass FROM pg_class WHERE oid IN ('pg_proc'::regclass, 'pg_toast.pg_toast_1255'::regclass, 'pg_proc_oid_index'::regclass) ORDER BY 1;
SELECT indexrelid::regclass, indkey, indclass FROM pg_index WHERE indrelid = 'pg_class'::regclass ORDER BY 1;
SELECT conname, contype FROM pg_constraint WHERE conrelid = 'pg_namespace'::regclass ORDER BY 1;
SELECT to_tsvector('italian', 'il gatto e la volpe');
